 const sessions=new Map();
 const safeMemes=['吃白饭的大肥鱼','大的要来啦','死掉了','深度睡眠','先养着吧','吃饱饱摸肚子','誓死践行开源精神','电死你','可爱','token给妈妈保管','厉害了我的鲸','哦鲸鲸','压力一只大肥鱼','黎曼猜想没证明喵','就一碗','Ciallo'];
 const state=k=>{if(!sessions.has(k))sessions.set(k,{decks:new Map(),texts:[],faces:[],images:[],topics:[]});return sessions.get(k);};
 const face=t=>t.match(/\([^A-Za-z0-9\u4e00-\u9fff]{3,18}\)/u)?.[0]||'';
 function pick(k,pool,lines){const s=state(k);let deck=s.decks.get(pool);if(!deck?.length){deck=[...lines.keys()];for(let i=deck.length-1;i;i--){const j=Math.floor(Math.random()*(i+1));[deck[i],deck[j]]=[deck[j],deck[i]];}s.decks.set(pool,deck);}
   let at=deck.findIndex(i=>!s.texts.slice(-5).includes(lines[i])&&(!face(lines[i])||!s.faces.slice(-5).includes(face(lines[i]))));
   if(at<0)at=deck.findIndex(i=>!s.texts.slice(-1).includes(lines[i]));if(at<0)at=0;
   const text=lines[deck.splice(at,1)[0]];s.texts.push(text);if(s.texts.length>12)s.texts.shift();s.faces.push(face(text));if(s.faces.length>5)s.faces.shift();return text;
 }
 function pickAction(k,name){return data.actions[name]?pick(k,'action:'+name,data.actions[name]):pickAmbient(k);}
 function pickAmbient(k,date=new Date()){const s=state(k),h=date.getHours(),m=date.getMonth()+1,d=date.getDay();
   const timed=h<6?'夜晚':h<11?'早晨':h<14?'午间':h<18?'午后':h<21?'傍晚':'夜晚';
   const season=m<=2||m===12?'冬日':m<=5?'春日':m<=8?'夏日':'秋日',week=d===0||d===6?'周末':d===1?'周初':'周中';
   const seasonal=['早晨','午间','午后','傍晚','夜晚','春日','夏日','秋日','冬日','周末','周初','周中'];
   const pool=[...Object.keys(data.ambient).filter(t=>!seasonal.includes(t)),timed,timed,season,week];
   const fresh=pool.filter(t=>!s.topics.slice(-4).includes(t));const topics=fresh.length?fresh:pool;const topic=topics[Math.floor(Math.random()*topics.length)];s.topics.push(topic);if(s.topics.length>5)s.topics.shift();return pick(k,'ambient:'+topic,data.ambient[topic]);
 }
 function pickMeme(k,text,action='',allowed=safeMemes){const s=state(k),context=action+' '+text;
   let names=/白饭|饭碗|添饭|吃|零食|馋/.test(context)?['就一碗','吃白饭的大肥鱼','吃饱饱摸肚子']:
    /困|睡|哈欠|夜晚/.test(context)?['深度睡眠','死掉了']:
    /反弹|戳|生气|爪子|挠|炸毛/.test(context)?['电死你','哦鲸鲸','压力一只大肥鱼']:
    /夸|可爱|厉害|得意|成功|聪明/.test(context)?['厉害了我的鲸','可爱']:
    /翻车|错|卡住|难题|失误|心虚/.test(context)?['压力一只大肥鱼','黎曼猜想没证明喵','哦鲸鲸']:
    /token|预算|钱袋|余额/.test(context)?['token给妈妈保管','哦鲸鲸']:
    ['先养着吧','哦鲸鲸','可爱'];
   names=names.filter(n=>allowed.includes(n));if(!names.length)names=safeMemes.filter(n=>allowed.includes(n));if(!names.length)return '';
   const fresh=names.filter(n=>!s.images.slice(-2).includes(n));const options=fresh.length?fresh:names;const image=options[Math.floor(Math.random()*options.length)];s.images.push(image);if(s.images.length>3)s.images.shift();return image;
 }
